type CustomerID string

type Customer struct {
    ID   CustomerID        // identity: set at creation, never reassigned
    Name string
}

func (c *Customer) Rename(name string) { c.Name = name }   // state may change

func (c *Customer) Equal(other *Customer) bool {
    return other != nil && c.ID == other.ID   // identity, not the fields
}
